python -c "import urllib.request, json
for m in ['silica-rtl-lora-v1', 'silica-spec-lora-v1', 'silica-verif-lora-v1', 'silica-synth-lora-v1']:
    try:
        req = urllib.request.urlopen(f'https://huggingface.co/api/models/SILICAM/{m}')
        data = json.loads(req.read())
        files = [s['rfilename'] for s in data.get('siblings', [])]
        print(f'=== {m} ===')
        print('Files:', files)
    except Exception as e:
        print(f'{m}: {e}')"

python -c "import urllib.request
for s in ['rtl', 'spec', 'verif', 'synth']:
    url = f'https://huggingface.co/api/datasets/SILICAM/silica-{s}-data'
    try:
        r = urllib.request.urlopen(url)
        print(f'dataset silica-{s}-data:', r.getcode())
